async function structured(name, task, data, externalSignal = null, requestContext = {}) {
  const schema = structuredOutputSchemas[name];
  if (!schema) throw new Error(`Unknown Structured Outputs schema: ${name}`);
  const timeout = REQUEST_TIMEOUT_BY_PHASE[name] ?? REQUEST_TIMEOUT_MS;
  const controller = new AbortController(); const startedAt = performance.now();
  const abortFromCaller = () => controller.abort();
  if (externalSignal?.aborted) controller.abort();
  else externalSignal?.addEventListener("abort", abortFromCaller, { once: true });
  let rejectDeadline;
  const deadline = new Promise((_, reject) => { rejectDeadline = reject; });
  const timer = setTimeout(() => {
    controller.abort();
    const error = new Error("OpenAI request timed out"); error.name = "AbortError";
    diagnostic("api_request_timeout", { phase: name, attempt: 1, timeout_ms: timeout });
    rejectDeadline(error);
  }, timeout);
  const outputLanguage = detectOutputLanguage(data);
  const separatedInput = buildStructuredInput(task, data);
  const input = separatedInput.input;
  const inputChars = JSON.stringify(input).length;
  diagnostic("ai_start", { phase: name, output_language: outputLanguage, max_output_tokens: OUTPUT_TOKEN_LIMITS[name], timeout_ms: timeout, input_chars: inputChars, schema_version: "v4.1", runtime_revision: "critical-product-impact-v1" });
  try {
    diagnostic("api_request_start", { phase: name, attempt: 1, input_chars: inputChars });
    const request = client(timeout).responses.parse({ model: process.env.OPENAI_MODEL || "gpt-5-mini", instructions: `${policy}\n\n${requirementGroundingPolicy}\n\n${questionPolicy}\n\n${inferencePolicy}\n\n${canonicalSpecPolicy}\n\n${providerSafetyInstruction}\n\nTask for this phase:\n${separatedInput.taskInstruction}\n\n${languageInstruction(data)}`, input, reasoning: { effort: "minimal" }, max_output_tokens: OUTPUT_TOKEN_LIMITS[name], store: false, text: { format: zodTextFormat(schema, name) } }, { signal: controller.signal });
    const response = await Promise.race([request, deadline]);
    const summary = responseDiagnostic(response); diagnostic("api_success", { phase: name, ...summary });
    diagnostic("ai_usage", usageDiagnostic(response, name, requestContext));
    if (!response.output_parsed) { const error = new Error("AIから有効な構造化レスポンスを取得できませんでした。"); error.name = "StructuredOutputMissingError"; error.diagnostic = summary; throw error; }
    diagnostic("sdk_parse_success", { phase: name });
    const validation = schema.safeParse(response.output_parsed);
    if (!validation.success) { diagnostic("zod_validation_error", { phase: name, issues: validation.error.issues.map((issue) => ({ path: issue.path, code: issue.code, message: issue.message })) }); const error = new Error("AIの構造化レスポンスがスキーマ検証に失敗しました。"); error.name = "StructuredOutputValidationError"; throw error; }
    diagnostic("zod_validation_success", { phase: name }); diagnostic("frontend_payload_ready", { phase: name, output_language: outputLanguage, elapsed_ms: Math.round(performance.now() - startedAt) });
    return validation.data;
  } catch (error) { if (controller.signal.aborted) error.name = "AbortError"; diagnostic("ai_error", { phase: name, elapsed_ms: Math.round(performance.now() - startedAt), type: error.name || "Error", response_status: error.status ?? null, incomplete_reason: error.diagnostic?.incomplete_reason ?? null }); throw error; } finally { clearTimeout(timer); externalSignal?.removeEventListener("abort", abortFromCaller); }
}

export const requirementsAI = {
  startProject: (idea, { signal, requestContext } = {}) => structured("initial_project", "Apply REQUIREMENT GROUNDING before relevance, material impact, or question necessity. Analyze this idea, including criticalProductDecisions, and return 2–4 project-specific dimensions. A criticalProductDecision is an independent Product Decision required to make the core value or primary flow implementable and for which materially different product behaviors remain. For every critical decision fill necessity, including every productImpact field. Mark it resolvedByInitialInput=true only when the user actually fixed it; exclude core invariants, implementation choices, optional features, and secondary/tertiary follow-on details. Every unresolved critical decision must be represented by a matching question decisionDomain. Mark explicit facts known=true. Initial questions must focus on product skeleton: users, core action/value, principal permissions, user-visible eligibility/selection rules, essential content/data boundaries, and details of explicitly mentioned features. Never ask for a technical provider, API protocol, sync frequency, database, UI placement, logging, or validation mechanics. A product-level choice about same-device versus shared/account-backed access, or about the source and coverage of essential content, is not a technical implementation detail when alternatives change the user-visible product. Ask no question just to increase question count. Keep titles concise, reasons under 80 characters, and up to four options.", { idea }, signal, requestContext),
  analyzeIdea: (idea, { signal, requestContext } = {}) => structured("project_analysis", "Apply REQUIREMENT GROUNDING before relevance, material impact, or question necessity. Analyze the project idea into explicit facts and genuine uncertainties. Also identify the primary-flow skeleton: targetUsers, managedObject, primaryAction, persistedOutcome, and successCondition. Return a value only when it is stated or uniquely determined by the idea; otherwise return null. Do not fill an ambiguity with a conventional CRUD, completion, status, archive, notification, loan, return, or approval flow. Populate criticalProductDecisions only with independent Product Decisions still needed for an implementation-ready core value or primary flow that pass the QUESTION NECESSITY TEST. For every item fill all necessity and productImpact fields. Evaluate materiality before safe defaults: if reasonable alternatives change core result eligibility/selection, essential content source or coverage, external-dependency boundary, data ownership/access, primary flow, permissions, or irreversible state, the choice is material and a merely simple conventional option is not a safe default. Basic direct entry is a safe MVP default when the idea says users register/input data but does not request recognition, scanning, import, sensors, or integration; do not create a critical decision by introducing those new capabilities as alternatives. If a decision follows from the initial input or a confirmed decision, set derivableFromConfirmedDecision=true. Use a stable semantic decisionDomain, a user-facing reason, and resolvedByInitialInput. Do not list Core Invariants, technical implementation choices, optional/future features, or second/third-order consequences of another decision. If the initial input already fixes a decision, include it with resolvedByInitialInput=true; otherwise false. A vague idea may leave more than one independent product decision unresolved, but merely being unspecified never makes a decision critical.", { idea }, signal, requestContext),
  generateDimensions: async (context, { signal, requestContext } = {}) => (await structured("specification_dimensions", "Apply REQUIREMENT GROUNDING before relevance, material impact, or question necessity. Generate project-specific MVP dimensions from the compact Canonical Decision Context. Return at most one dimension for each unresolved analysis.criticalProductDecisions item and no extra dimensions. For every unresolved item, return a Product-Language question with exactly the same semantic decisionDomain unless it is already settled by a User Confirmed Decision or uniquely-derived AI requirement. Never omit an unresolved critical decision merely because another question exists. Do not ask about a settled decisionDomain, a uniquely-derived requirement, or a coreInvariant, even when a new key or wording is used. Only attach questions that pass the supplied necessity fields. A reservation conflict invariant is not a question. Never introduce generic genre features or ask for technical vendors, API protocols, sync frequency, database choice, UI layout, logging, or validation mechanics. Preserve product-level questions about result eligibility, essential content/data boundaries, and data ownership/access when analysis marks them material. Every title, intent, option, recommendation, and reason must avoid API, endpoint, scraping, OCR, database, schema, protocol, implementation, and vendor terminology. Express essential content sourcing as built-in content versus content supplied by an outside service, and data ownership as same-device use versus account-backed use across devices. Use two or three concise options per question.", compactQuestionContext(context), signal, requestContext)).items,
  inferMvp: (context, { requestContext } = {}) => structured("mvp_inference", "Apply REQUIREMENT GROUNDING before relevance, material impact, or question necessity. User Confirmed Decisions are immutable top-level constraints. Never weaken, strengthen, reinterpret, narrow for MVP convenience, or override them through inferred requirements, proposals, rules, or acceptance criteria. On every call, reassess the initial idea, User Confirmed Decisions, existing AI-Inferred Requirements, and primary-flow skeleton. Put a remaining decision in criticalProductDecisions only if it independently passes the QUESTION NECESSITY TEST, and fill every necessity and productImpact field. Evaluate whether alternatives materially change product behavior before considering a safe default. Do not infer a choice merely because one option is cheaper or conventional when alternatives change core output eligibility/selection, essential content source or coverage, external-dependency boundary, data ownership/access, primary flow, permissions, or irreversible state. If an answer is reasonably derivable from a User Confirmed Decision, infer it and do not ask. Do not recursively promote consequences of a confirmed decision: approval expiry, rejection history, withdrawal notification, history display, fine editing permissions, reminder behavior, and notification presentation normally use conservative reversible defaults. Do not use an AI-Inferred Requirement to settle a genuinely user-owned material choice. If eligible criticalProductDecisions is non-empty, generate exactly one clarificationQuestions entry for its highest-impact decisionDomain, using the exact same semantic decisionDomain. A genuine Product Decision remains unresolved until the user confirms it. If completionGate.unresolvedCriticalProductDecisions is non-empty, address only those genuine user-owned decisions. Derive questions from the core value and primary flow, not from a fixed genre template. Core Invariants and implementation details are not eligible questions. Every clarification question must include all necessity fields and pass: (requiredForCoreValue OR requiredForPrimaryFlow OR clarifiesExplicitUserRequest OR changesProductBehavior), implementationDetailOnly=false, derivedOnlyFromAIInference=false. Do not ask about PIN policy, database/API protocol or vendor, UI placement, logging, validation mechanics, exports, backup, analytics, or sync frequency. A user-visible local-only versus shared/account-backed data boundary may be a Product Decision; the storage engine and synchronization mechanism are not. For every aiInferredRequirement, necessity must show YES for at least one of: required to realize a confirmed decision, core user value, or primary user flow. If all three are NO, use implementationProposals or futureOptional instead. For a core AI/recognition/processing capability with an unresolved material technical approach that preserves the same user-visible product, add exactly one concrete recommended Implementation Proposal; never ask the user to choose the vendor/library. Before completing inference, assess every primary state transition using trigger, state before, state after, persisted data change, and next automatic-rule evaluation. Return stateTransitionGaps=[] only when every major transition is complete. If one safe conservative reversible MVP default resolves a nonmaterial gap, return an AI-Inferred Requirement and set requiresProductDecision=false. Do not create a state-gap question for DB, API, cache, logs, retry, or UI details. Return the smallest useful result: at most 3 inferred requirements, 1 proposal, 2 future items, 1 clarification, 2 stateTransitionGaps, and 3 criticalProductDecisions. Every value, reason, and proposal description must be a complete grammatical sentence; never end a field mid-word or mid-sentence. Do not output answered or known dimensions. Never use one key in more than one category.", compactInferenceContext(context), null, requestContext),
  auditCriticalDecisionCoverage: async (context, { requestContext } = {}) => {
    const result = await structured("critical_decision_coverage_audit", "Apply REQUIREMENT GROUNDING before relevance, material impact, or question necessity. Perform an independent pre-completion coverage audit. Do not accept earlier safe-default classifications without re-evaluating them. Ask whether an implementer would still need to choose among materially different user-visible product behaviors, even if any one option could produce a technically working MVP. Discover missing semantic decision domains generically; never use a genre checklist or fixed question count. For each discovered item fill every necessity and productImpact field and evaluate materiality before safe defaults. Reasonable alternatives in core result eligibility/selection, essential content source or coverage, external-dependency boundary, data ownership/access, primary flow, permissions, or irreversible state are Product Decisions; a cheap or conventional option does not make them safe to infer. By contrast, form details, provider/vendor, library, algorithm implementation, database product, API protocol, storage engine, sync frequency, transaction/locking method, logging, retry, cache, display details, and secondary/tertiary follow-ons are nonblocking when they preserve the same product behavior. When the idea already says users register/input data but does not mention recognition, scanning, import, sensors, or integration, treat basic direct entry as the safe default and do not invent those new capabilities as a Product Decision. If an eligible critical Product Decision is missing, set coverageComplete=false, list newly discovered independent domains, and return exactly one Product-Language clarification question for the highest-impact domain. Do not repeat answered, inferred, invariant, approved-final, or already-unresolved domains. If no new question-necessary critical decision or product-owned state-transition gap exists, set coverageComplete=true even when noncritical details remain. auditedDecisionDomains should list semantic areas actually examined, not a fixed taxonomy.", compactInferenceContext(context), null, requestContext);
    const hasBlockingDiscovery = result.criticalProductDecisions.length > 0 || result.stateTransitionGaps.some((gap) => gap.requiresProductDecision);
    if (!result.coverageComplete && !hasBlockingDiscovery) {
      const error = new Error("重要な意思決定の網羅性監査結果が不完全です。再試行してください。");
      error.name = "CoverageAuditInvariantError";
      throw error;
    }
    return result;
  },
  generateSpec: async (context, { requestContext } = {}) => ({ spec: await structured("generated_spec", "Generate the v4.1 SPEC body from ProjectContext. User Confirmed Decisions are immutable and take precedence over every other source. Do not weaken, narrow, reinterpret, or replace their meaning for MVP convenience. If a confirmed decision remains ambiguous, do not generate a reduced implementation; return content that preserves it and let the clarification question be answered first. Copy every confirmed business-rule comparison operator, enum, and condition unchanged across MVP Scope, User Flow, Functional Requirements, State Transitions, Implementation Rules, and Acceptance Criteria. coreUserValue must state the user's value in one clear sentence. User Confirmed Decisions, AI-Inferred Requirements, Implementation Proposal, and Future / Optional are rendered by the app, so do not duplicate them. Keep AI-Inferred Requirements to independent user-visible capabilities: merge semantic duplicates that express the same user value, flow, and acceptance behavior even when their keys differ. An AI-inferred item may enter mandatory sections only when Canonical Requirements already marks it uniquely derived from a direct one-step source, traceable to a source decision or exact initial-input span, and indispensable. A proposal, Future / Optional item, optional user phrase, or any multi-step derived feature must never enter MVP Scope, Functional Requirements, Data Model, State Transitions, Implementation Rules, Error Handling, or Acceptance Criteria. Do not introduce completion, archive, deletion, status, approval, history, notification, loan, return, or disposal as a new product concept unless Canonical Requirements already contains it. Do not turn a game’s optional time attack or scoring into high scores, progress saving, stage selection, unlock rules, or other new mandatory product features. If a confirmed edit policy distinguishes mandatory review from optional modification, preserve that exact distinction in User Flow, Functional Requirements, Implementation Rules, and Acceptance Criteria. Never invent thresholds, durations, status sets, conflict states, alternatives, notification channels, or numeric values. Use qualitative language for an unconfirmed value rather than choosing a number. Do not mark a confirmed input field optional or required by convention; do so only when Canonical Requirements explicitly contains a reasoned uniquely-derived rule. For each Canonical primary state transition include trigger, state before, state after, persisted data change, and next automatic-rule evaluation. Do not invent a completion action merely to satisfy this format. Do not reveal reservation details to a user whose confirmed visibility/privacy decision does not authorize access. Each Data Model field must be required by an explicit decision, explicit request, or indispensable core flow; write balanced { }, [ ], and ( ) delimiters. Follow canonicalRequirements.dataBoundary and generationConstraints exactly: local-only means same-device local data, never an inferred network synchronization. Correct validationIssues by correcting their canonical cause or neutralizing the generated expansion. Keep every section concrete and within 500 characters.", context, null, requestContext) }),
  validateSpec: (context, spec, { requestContext } = {}) => structured("validation_result", "Validate the final v4.1 SPEC body, not internal provenance. ProjectContext may intentionally retain the same item in facts, inferredDecisions, and category arrays; this is never an error. The app canonicalizes final categories with precedence User Confirmed > AI-Inferred > Implementation Proposal > Future / Optional. Only report errors for a missing required SPEC section, contradictory user-confirmed decisions, or a Future / Optional or Implementation Proposal that the final MVP Scope, Functional Requirements, or Acceptance Criteria explicitly makes mandatory. Similarity, technical alternatives, or duplicate internal records are warnings only. If no blocking problem exists return valid=true; warnings may still be returned. Return at most five concise issues.", { context, spec }, null, requestContext),
};
export function apiError(error) {
  if (error.status === 503) return { status: 503, message: error.message };
  if (["APIConnectionTimeoutError", "APIUserAbortError", "AbortError"].includes(error.name) || error.code === "ETIMEDOUT") return { status: 504, message: "OpenAI APIがタイムアウトしました。再試行してください。" };
  if (error.status === 429) return { status: 429, message: "OpenAI APIのレート制限に達しました。少し待って再試行してください。" };
  if (error.status === 401) return { status: 502, message: "OpenAI APIキーを確認してください。" };
  if (error.status >= 400) return { status: 502, message: "OpenAI APIとの通信に失敗しました。再試行してください。" };
  return { status: 500, message: error.message || "AI処理に失敗しました。再試行してください。" };
}


